import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"06 - WebSocket Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/authentication-platforms.md","filePath":"developers/design-documentation/authentication-platforms.md"}'),s={name:"developers/design-documentation/authentication-platforms.md"};function n(d,e,c,i,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="_06-websocket-architecture" tabindex="-1">06 - WebSocket Architecture <a class="header-anchor" href="#_06-websocket-architecture" aria-label="Permalink to &quot;06 - WebSocket Architecture&quot;">​</a></h1><h2 id="two-real-time-channels" tabindex="-1">Two Real-Time Channels <a class="header-anchor" href="#two-real-time-channels" aria-label="Permalink to &quot;Two Real-Time Channels&quot;">​</a></h2><p>Tradeboard uses two different real-time mechanisms:</p><table tabindex="0"><thead><tr><th>Channel</th><th>Purpose</th><th>Client</th></tr></thead><tbody><tr><td>Socket.IO</td><td>Order lifecycle, analyzer refresh, sandbox engine events, UI notifications</td><td>React app</td></tr><tr><td>WebSocket proxy on port 8765</td><td>Normalized broker market data</td><td>SDKs, React market-data manager, risk monitor</td></tr></tbody></table><p>They are not interchangeable. Socket.IO events originate from the in-process EventBus; market-data messages originate from broker adapters and the ZMQ bus.</p><h2 id="market-data-topology" tabindex="-1">Market-Data Topology <a class="header-anchor" href="#market-data-topology" aria-label="Permalink to &quot;Market-Data Topology&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>broker adapter PUB sockets</span></span>
<span class="line"><span>        | connect</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>tcp://127.0.0.1:5555</span></span>
<span class="line"><span>        ^ bind</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>WebSocket proxy SUB socket</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>subscription index -&gt; authenticated WebSocket clients</span></span></code></pre></div><p>The SUB side binds and publisher sockets connect. This permits multiple broker/worker publishers to fan into one proxy under gunicorn/eventlet. Reversing the topology can drop ticks in multi-process deployments.</p><h2 id="proxy-lifecycle" tabindex="-1">Proxy Lifecycle <a class="header-anchor" href="#proxy-lifecycle" aria-label="Permalink to &quot;Proxy Lifecycle&quot;">​</a></h2><p><code>websocket_proxy/app_integration.py</code> chooses the execution model:</p><ul><li>Under eventlet/gunicorn, start the asyncio WebSocket proxy as a child process.</li><li>Under direct development startup, run it in a real OS thread.</li><li>Docker or standalone-proxy modes can suppress embedded startup.</li></ul><p>The server listens on <code>WEBSOCKET_HOST</code>/<code>WEBSOCKET_PORT</code> (default port 8765), uses explicit <code>WS_MAX_QUEUE</code>, <code>WS_PING_INTERVAL</code>, and <code>WS_PING_TIMEOUT</code>, and closes clients, adapters, ZMQ sockets, and the server socket during shutdown.</p><h2 id="protocol" tabindex="-1">Protocol <a class="header-anchor" href="#protocol" aria-label="Permalink to &quot;Protocol&quot;">​</a></h2><p>Clients send JSON action envelopes. Supported actions are:</p><table tabindex="0"><thead><tr><th>Action</th><th>Purpose</th></tr></thead><tbody><tr><td><code>authenticate</code> (alias <code>auth</code>)</td><td>Verify <code>api_key</code> or <code>apikey</code> and resolve broker</td></tr><tr><td><code>subscribe</code></td><td>Subscribe one <code>symbol</code> or a <code>symbols</code> array</td></tr><tr><td><code>unsubscribe</code></td><td>Remove selected subscriptions</td></tr><tr><td><code>unsubscribe_all</code></td><td>Remove all subscriptions for the client</td></tr><tr><td><code>subscribe_orders</code></td><td>Account-scoped order-update stream, no symbol or mode</td></tr><tr><td><code>unsubscribe_orders</code></td><td>Stop the order-update stream</td></tr><tr><td><code>get_broker_info</code></td><td>Return active broker/capability information</td></tr><tr><td><code>get_supported_brokers</code></td><td>Return proxy-supported brokers</td></tr><tr><td><code>ping</code></td><td>Protocol keepalive/diagnostic</td></tr></tbody></table><p><code>server.py</code> reads the action from either <code>action</code> or <code>type</code>, so both spellings work for the same envelope.</p><p>Authentication must complete within the configured grace period (15 seconds by default). Subscription modes accept <code>LTP</code>, <code>Quote</code>, or <code>Depth</code>, with integer modes 1, 2, and 3 normalized to those values. Responses report per-symbol success or failure.</p><h2 id="subscription-and-adapter-model" tabindex="-1">Subscription And Adapter Model <a class="header-anchor" href="#subscription-and-adapter-model" aria-label="Permalink to &quot;Subscription And Adapter Model&quot;">​</a></h2><p>The proxy indexes subscribers by normalized symbol, exchange, and mode, and constructs broker adapters through <code>websocket_proxy/broker_factory.py</code>. Connection pooling limits are controlled by environment settings, with defaults of 1000 symbols per broker connection and three connections.</p><p>Public market data is fanned out to matching clients by symbol, exchange and mode. Order updates are a separate, account-scoped channel: a client must explicitly send <code>subscribe_orders</code>, and the stream is never fanned out as part of a market-data subscription. Order-update ingestion itself is governed by <code>ORDER_UPDATES_ENABLED</code> (default <code>TRUE</code>), with <code>ORDER_POLL_INTERVAL</code> (default 5 seconds) used for brokers that have no push mechanism. Position and margin topics are not published on the proxy at all.</p><h2 id="shared-broker-feed" tabindex="-1">Shared Broker Feed <a class="header-anchor" href="#shared-broker-feed" aria-label="Permalink to &quot;Shared Broker Feed&quot;">​</a></h2><p>All app sessions share one installation-level broker feed. Re-authenticating another device with unchanged broker and feed tokens does not publish teardown invalidation. A material token/broker/revoke change still invalidates caches and feed state.</p><h2 id="frontend-use" tabindex="-1">Frontend Use <a class="header-anchor" href="#frontend-use" aria-label="Permalink to &quot;Frontend Use&quot;">​</a></h2><p><code>frontend/src/lib/MarketDataManager.ts</code> centralizes client subscriptions. Hooks acquire and release subscriptions rather than opening independent connections per component. Page visibility and stale-tick fallbacks limit unnecessary traffic. The scalping server risk monitor uses <code>services/websocket_client.py</code> so stop evaluation survives browser navigation.</p><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>websocket_proxy/server.py</code></td><td>Protocol, auth, subscription index, delivery</td></tr><tr><td><code>websocket_proxy/app_integration.py</code></td><td>Thread/process startup choice</td></tr><tr><td><code>websocket_proxy/broker_factory.py</code></td><td>Adapter creation</td></tr><tr><td><code>websocket_proxy/connection_manager.py</code></td><td>Pooling and connection state</td></tr><tr><td><code>services/websocket_service.py</code></td><td>ZMQ publisher used by broker data paths</td></tr><tr><td><code>services/websocket_client.py</code></td><td>Internal proxy client</td></tr><tr><td><code>frontend/src/lib/MarketDataManager.ts</code></td><td>Browser subscription manager</td></tr></tbody></table><p>See the <a href="./../../api-documentation/v1/websockets.html">WebSocket API</a> for client messages.</p>`,27)])])}const u=t(s,[["render",n]]);export{b as __pageData,u as default};
